def find_euler_tour(n, a):
    # Variables to determine if Euler tour is possible
    can_euler_tour = False
    length = n * 2 - 1
    result = [None] * length

    if length % 2 == 1:
        can_euler_tour = True
        result[n] = 1

    for i in range(0, length, 2):
        if a[i] == 0:
            error = True
            for j in range(i, length, 2):
                if a[j] != 1 and a[j] != 2:
                    error = False
                    break
            if error:
                return "no"  # This means single occurrence
        else:
            if (a[i] - 1 + a[i + 1]) % 2 != 0:
                return "no"  # This generated arcs are not reciprocal
            bin_set = 0
            bin_total = 0
            j = i
            while j <= length - 1 - i:
                bin_set |= 1 << a[j]
                bin_total += a[j]
                j += 2

            if bin_set == bin_total + 1 or bin_total == bin_set:
                can_euler_tour = True
                result[bin_set] = a[i]
                result[n] = n - bin_total

    if not can_euler_tour:
        return "no"
    else:
        return "yes\n" + " ".join(str(num) for num in result)

# Example usage
