```python
import heapq

# Function to dijkstra_path_costs(dijkstra_path_cost_table, node_from, node_to, plan_edge)
def dijkstra_path_costs(dijkstra_path_cost_table, node_from, node_to, plan_edge):
    # Use a priority queue to handle the shortest path
    queue = [(0, node_from, [])]
    cost_so_far = {}
    cost_so_far[node_from] = 0

    while queue:
        current_cost, current_node, path = heapq.heappop(queue)
        if current_cost > cost_so_far[current_node]:
            continue
        if current_node in cost_so_far and cost_so_far[current_node] < current_cost:
            return cost_so_far + {None: current_cost}, path

        if current_node == node_to:
            shortest_path_cost = cost_so_far[node_to] + plan_edge
            return shortest_path_cost, path + [node_to]

        for neighbor, weight in dijkstra_path_cost_table[current_node].items():
            if neighbor in cost_so_far:
                updated_cost = current_cost + weight + plan_edge
                new_path = path + [current_node]
            else:
                updated_cost = current_cost + weight + plan_edge
                new_path = []

            if sorted(new_path) not in dijkstra_path_cost_table[neighbor].keys() or updated_cost < cost_so_far.get(sorted(new_path), float('inf')):
                cost_so_far[sorted(new_path)] = updated_cost
                heapq.heappush(queue, (cost_so_far[sorted(new_path)], sorted(new_path), new_path))

    return float('inf'), []

