from heapq import heappush, heappop

def dijkstra(graph, start, end):
    n = len(graph)
    distances = [float('inf')] * n
    distances[start] = 0
    queue = [(0, start)]

    while queue:
        current_distance, current_vertex = heappop(queue)

        if current_distance > distances[current_vertex]:
            continue

        for neighbor, weight in graph[current_vertex].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(queue, (distance, neighbor))

    return distances[end]

def calculate_fees(towns, roads, plans):
    lowest_fees = []
    graph = {town_id: {} for town_id in range(towns)}

    for u, v, price in roads:
        graph[u-1][v-1] = price
        graph[v-1][u-1] = price

    for t, x in plans:
        cheapest_path = float('inf')
        for u in range(towns):
            for v, x_road in graph[u].items():
                if x_road != x:
                    path_fee = sum(graph[u][coord] for coord in range(towns)) + x
                    cheapest_path = min(cheapest_path, path_fee + cheapest_path)
            graph[t-1][u-1] = x
            lowest_fees.append(cheapest_path)

    return lowest_fees

# Example input
