    factors = {}
    while i * i <= n:
        while (n % i) == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            n //= i
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

def equal_divisors(a, b):
    a_factors = prime_factors(a)
    b_factors = prime_factors(b)

    common_factors = dict(filter(lambda x: x[1] > 2, a_factors.items()))

    d = 0
    for factor, count in common_factors.items():
        if factor not in b_factors or b_factors[factor] % factor != 0:
            d += (count + 1) // 2
    return d

