from collections import deque, defaultdict
from typing import List

def restore_Euler_tour(indices: List[int]) -> bool:
    if len(indices) % 2 != 1:
        return False
    left, right = deque(), []
    index = len(indices) // 2  # start from index 1

    for i, index in enumerate(indices):
        if index == 0:
            left.appendleft(index)  # fill left deque
            continue
        left.append(index)
        right.append(i % 2 if i % 2 == 0 else len(index) - i - 1)  # find the index of the "legible number"

    # check if all numbers are used and matches sequence
    def check_sequence():
        for i in indices:
            if len(i) > 1:
                if i[0] in right:
                    return i[::-1]
        return False

    if not check_sequence():
        return False

    # check revese sequence
    index = 0
    for i in range(len(right)):
        if index > len(right) - i:
            return False
        if not right:
            left.appendleft(0)
            continue
        if right[0] in left:
            right.pop(0)
            index += 1
        else:
            left.pop()
            right.pop()
    
    return True

