def get_longest_common_suffix(words):
    suffixes = [[word, word[-1:], len(word) - 1] for word in words]
    suffixes.sort(key=lambda x: x[1], reverse=True)
    for i in range(1, min(len(suffix) for word, suffix, _ in suffixes)):
