            for j in range(length - i):
                if word[-i] != word[-j-1]:
                    suffixes[i-1] = [word, suffix[-i:], length - i]
                    suffixes.pop()
                    break
    longest_suffix = suffixes[0][1]
    if longest_suffix:
        return len(longest_suffix)
    return 0

