from typing import List

def compute_min_length(string1, string2):
    i, j = 0, 0
    min_length = 0
    while i < len(string1) and j < len(string2):
        if string1[i] == string2[j]:
            min_length += 1
        else:
            break
        i += 1
        j += 1
    return min_length

def compute_beauty(word: List[str], n: int) -> int:
    beauties = set()
    for i in range(2 ** min(n, len(word))):
        mid_point = (i + n) // 2
        subsequence = word[mid_point : mid_point + n]
        prefix_common = compute_min_length(subsequence, word[0])
        suffix_common = compute_min_length(subsequence, word[-1])
        beauty = min(prefix_common, suffix_common) ** 2
        beauties.add(beauty)
    return max(beauties)

def main():
    T = int(input().strip())
    for _ in range(T):
        N = int(input().strip())
        words = [input().strip() for _ in range(N)]
        print(compute_beauty(words, N))

if __name__ == "__main__":
