def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        while (n % i) == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

def find_min_operations(a, b):
    primes = [2]
    if a >= 4:
        primes.append(2)
    if b >= 8:
        primes.append(2)
    factors_a = prime_factors(a)
    factors_b = prime_factors(b)
    def lcm_factors(factors):
        from functools import reduce
        from operator import mul
        return reduce(mul, factors, 1)
    for p in primes:
        count_a, count_b = 0, 0
        for factor in factors_a:
            if factor % p == 0:
                count_a += 1
        for factor in factors_b:
            if factor % p == 0:
                count_b += 1
        new_a, new_b = a * p, b // p
        if count_a + 1 == len(factors_a):
            new_factor_a = []
            for x in factors_a:
                if x % p != 0:
                    new_factor_a.append(x)
            count_new_a = 0
            for new_factor in new_factor_a:
                for factor in factors_b:
                    if new_factor % factor == 0 and factor % len(new_factor) == 0:
                        count_new_a += 1
            if count_new_a == len(factors_b):
                count_a += 1
        else:
            count_a += 1
        if count_a <= len(factors_a) or count_b <= len(factors_b):
            a = new_a
            b = new_b
        factors_a = new_factor_a
    if count_a <= len(factors_a) or count_b <= len(factors_b):
        return 1
    a //= 2
    if a > 1:
        if isqrt(a) * isqrt(a) == a:
            return 2
    return 0

