from math import sqrt, isqrt, gcd
from collections import defaultdict

def p_sieve(n):
    """Return a dictionary where keys are prime numbers and values are their indexes in the list."""
    sieve = list(range(n+1))
    for i in range(2, int(isqrt(n)) + 1):
        lmt = int(n / i) - 1 # lmt will be first index right after last multiple of i
        for j in range(i*i, lmt, i):
            sieve[j] = 0
    p_idx = defaultdict(list)
    for idx, val in enumerate(sieve):
        if val:   # val is 1 that means val is a prime number
            p_idx[val[1]].append(idx)
    return p_idx

def isPrime(n):
    """Return True for prime number and False for non prime positive integer."""
    return n > 1 and all(n%i for i in range(2,isqrt(n)+1)) or n == 1

def primeFactors(n, p_idx):
    """Return a list of prime factors for number n from prime_index array (the values at end is sorted)."""
    arr = []
    ind = p_idx[n]
    prev = [-1]
    for i in range(0, len(p_idx)):
        if p_idx[i] <= ind:
            prev_p = prev[-1]
            prev = p_idx[i][::]
            count = 0
            while prev_p and prev_p <= ind:
                prev_p = p_idx[i][::]
                prev += count*[p_idx[end][0] for end in p_idx[i][::] if p_idx[i][0] in prev_p]
                ind -= 1
            arr += prev[-count:][::-1]
    return arr

