class UnionFind:
    def __init__(self):
        self.parent = {}
        self.rank = {}

    def find(self, x): # Find the root of x (pe
        if x not in self.parent:
            self.parent[x] = x
            self.rank[x] = 0
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return self.parent[x]
    def union(self, a, b): # Union a and b (pe
        rootA = self.find(a)
        rootB = self.find(b)
        if rootA != rootB:
            if self.rank[rootA] > self.rank[rootB]:
                self.parent[rootB] = rootA
                self.rank[rootA] += 1
            elif self.rank[rootA] < self.rank[rootB]:
                self.parent[rootA] = rootB
                self.rank[rootB] += 1
            else:
                self.parent[rootB] = rootA
                self.rank[rootA] += 1

def count_divisors(n):
    if n == 1:
        return 1
    total = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                total += 1
            else:
                total += 2
    return total

