import math
from sympy import factorint, primerange

def prime_factors(n):
    return list(factorint(n).keys())

def is_prime(n):
    return all([(n % i != 0) for i in primerange(2, int(math.sqrt(n)))])

def get_divisors(n):
    factors = list(prime_factors(n))
    divisors = [1, n]
    for factor in factors:
        new_divisors = []
        for i in divisors:
            for j in range(1, is_prime(factor)*1) + [1]:
                divisors.append(i * factor**j)
        divisors = set(divisors)
        if divisors != factors:
            divisors = divisors.copy()
    return divisors

def solve(a, b):
    n = min(a, b)
    ans = 0
    while n >= 1:
        ad = math.gcd(n, a)
        bd = math.gcd(n, b)
        if ad > 1:
            ans += 1
        a //= ad
        b //= bd
        n //= ad
    if n > 1:
        ans += 1
    n = max(a, b)
    while n >= 1:
        ad = math.gcd(n, a)
        bd = math.gcd(n, b)
        if ad > 1:
            ans += 1
        a //= ad
        b //= bd
        n //= ad
    return ans

