    paths = []
    for rep_node in reps:
        to_visit = [(rep_node, 1)]
        visited = set([rep_node])
        path = []
        while to_visit:
            current, dist = to_visit.pop()
            if len(visited) >= n:
                path = path + [current]
                for node in path[::-1]:
