        elif state == 1:
            index += 1
        elif state == 2:
            if tour[2*index+1] == 0:
                indices.append(2*index+1)
                index += 1
            elif tour[2*index+1] == 1 and 2*index+1 + 1 < n:
                indices.append(2*index+1 + 1)
                tour[index] = 2*n - 1
                index += 1
            else:
                state = 0

    if len(indices) == n and (2*n-1) * 2 - 1 - n == indices[-1]:
        return "yes\n" + " ".join(map(str, tour))
    else:
        return "no"

print(euler_tour())
