def find_xor_pairs(n, nums):
    xor_pairs = []
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    if (nums[i] ^ nums[j]) == (nums[k] ^ nums[l]):
                        xor_pairs.append([i, j, k, l])
    return xor_pairs

