def find_solution(n, a):
    total_candies = sum(a)
    if total_candies % 3 != 0:
        return -1  # Cannot be split equally into two non-empty boxes

    target_per_box = total_candies // 3
    sorted_a = sorted(a)

    moves = []
    for i in range(n - 1, 0, -1):
        if sorted_a[i] >= target_per_box + (i < n) * target_per_box:
            target_per_box -= sorted_a[i]
            moves.append((i, i - 1))

    if target_per_box > 0:
        return -1  # Cannot be reduced further

    return len(moves)

# Example usage:
print(find_solution(3, [3, 6, 9]))  # Output: 2
print(find_solution(3, [0, 1, 0]))  # Output: -1
print(find_solution(4, [0, 1, 1, 0]))  # Output: 0
